package security

import("crypto/subtle";"net/http";"os";"strings")
func Middleware(next http.Handler)http.Handler{if next==nil{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){http.Error(w,"handler unavailable",http.StatusServiceUnavailable)})};token:=strings.TrimSpace(os.Getenv("FTN_API_AUTH_TOKEN"));if token==""{return next};return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){if r==nil{http.Error(w,"bad request",http.StatusBadRequest);return};if r.URL.Path=="/healthz"||r.URL.Path=="/readyz"||r.URL.Path=="/metrics"{next.ServeHTTP(w,r);return};auth:=strings.TrimSpace(r.Header.Get("Authorization"));if !strings.HasPrefix(auth,"Bearer "){http.Error(w,`{"error":"unauthorized"}`,http.StatusUnauthorized);return};supplied:=strings.TrimSpace(strings.TrimPrefix(auth,"Bearer "));if supplied==""||subtle.ConstantTimeCompare([]byte(supplied),[]byte(token))!=1{http.Error(w,`{"error":"unauthorized"}`,http.StatusUnauthorized);return};next.ServeHTTP(w,r)})}
